// Reviewed workflow descriptions. The guide builder adds current screen labels, fields,
// actions, validation messages, navigation paths, and source fingerprints from these files.
module.exports = [
  {
    id: "system-overview", category: "System & roles", title: "System modules and functions", keywords: ["all functions", "all modules", "system overview", "features", "capabilities", "what can", "buong system"],
    sources: ["src/components/navigation/Sidebar.jsx", "src/utils/roleRoutes.js", "src/utils/permissions.js"], extract: false,
    answer: "This HRIS supports role-based dashboards; employee and account management; profiles and PDS; divisions, positions and signatories; service records and salary notices; leave applications and balances; leave monetization; travel orders; pass slips and QR scanning; compensatory time off and COC credits; overtime and accomplishment reports; attendance import and DTR; payroll preparation, approval, payout and payslips; MGB Coop loans; IPCR and OPCR performance; promotions; rewards, nominations, employee voting, loyalty awards and certificates; reports and analytics; calendars, holidays and announcements; messages and notifications; roles, permissions, audit logs, backups and security settings. The same module can show different records and actions for each role. Ask about a particular task for its procedure."
  },
  {
    id: "role-access", category: "System & roles", title: "Roles, permissions and approval responsibilities", keywords: ["role", "permission", "administrator", "admin", "hr head", "hr staff", "chief admin", "division chief", "planning officer", "regional director", "cashier", "employee", "access denied"],
    sources: ["src/utils/permissions.js", "src/page/settings/permission.jsx", "src/page/chiefadmin/chiefadmindashboard.jsx", "backend/api/auth.php"], extract: false,
    answer: "Built-in portals are Admin, HR Head, HR Staff, Division Chief, Chief Admin, Planning Officer, Cashier, Regional Director and Employee. Admin manages master data, users, roles and settings. HR Staff maintains operational records and first-stage leave verification; HR Head performs HR review and management. Division Chiefs handle division-scoped reviews, performance and promotion preparation. Only the FAD/FAM Division Chief has the Chief payroll desk; Chief Admin does not inherit that payroll role. Planning Officers recommend travel orders and can perform configured division leave actions. The Regional Director handles final approvals and OPCR validation. Cashier handles payroll payout and personal request filing. Employees use their own records and requests. Custom roles inherit a configured base role and can have permission overrides; the custom Finance role uses an HR Head-based portal but is treated as a payout desk in payroll rather than an HR Head approver. Actual module/action permissions and workflow stage checks determine access; a role name alone does not grant every action. Messages and notifications are shared utilities."
  },
  {
    id: "dashboards", category: "System & roles", title: "Dashboards, summaries and quick actions", keywords: ["dashboard", "summary", "quick actions", "analytics", "welcome", "employee profile", "chart"],
    sources: ["src/components/dashboard/EmployeeDashboardView.jsx", "src/components/dashboard/AdminAnalyticsOverview.jsx", "src/components/dashboard/DivisionDashboardOverview.jsx", "src/components/dashboard/CashierDashboardOverview.jsx"],
    answer: "Open Dashboard from your portal's sidebar. Dashboard content is scoped to the current role and may include employee profile details, leave credits, attendance, request counts, performance, payroll or division summaries. Employee quick actions include File Leave, View Attendance, View Payslip and Update Profile. Choose a period/filter on a chart where available and open the underlying module for the full records. Empty or loading cards do not establish that a record was deleted; review its module or retry a failed data load. Header controls provide theme switching, Help & FAQ, messages, notifications and your account menu."
  },
  {
    id: "employee-management", category: "Employees & organization", title: "Employee management and employee directory", keywords: ["employee management", "employee directory", "add employee", "import employees", "employment", "archive employee", "team", "division employee"],
    sources: ["src/module/employee/EmployeeManagementWorkspace.jsx", "src/components/employee/AdminEmployeeCard.jsx", "src/components/employee/TeamEmployeeProfile.jsx", "backend/api/employee.php"],
    answer: "Open Employee Management or Employee Directory from a portal with employee permissions. Search and filter the list, then open an employee card for the available details. Authorized management users can add/edit employee information, assignment, employment status, date hired and salary-related master fields; complete required fields before saving. The employee form can include profile photos and supporting documents. A Division Chief's team view is scoped to their division. Employee records and user login accounts are related but distinct. Use the archive/restore actions when available rather than assuming an archive is permanent deletion. Import and export options are available where shown. Changing appointment-related position/salary fields can create service-record history, so review the employee and effective information before saving."
  },
  {
    id: "employee-documents", category: "Employees & organization", title: "Employee document uploads and retrying failed attachments", keywords: ["birth certificate", "valid id", "resume", "diploma", "employee documents", "attachment", "retry upload"],
    sources: ["src/components/employee/EmployeeDocumentManager.jsx", "src/components/employee/EmployeeDocumentUploadFields.jsx", "src/components/employee/EmployeeDocumentRetryModal.jsx", "backend/api/employee_documents.php"],
    answer: "Open the employee record's Documents action or the document fields on the employee form. Select the document type and an accepted file, then use the upload/save action shown. Document types include birth certificate, valid IDs, resume and diploma. Saving an employee and uploading its documents are separate operations: a saved employee record can remain valid if one attachment fails. The retry dialog keeps failed files so you can retry those uploads. A document must be attached to a valid saved employee record. Viewing/downloading/removing documents follows the record access permissions and the controls available to your role."
  },
  {
    id: "user-management", category: "Employees & organization", title: "User accounts, activation and employee linking", keywords: ["user management", "add user", "create account", "activate", "deactivate", "temporary password", "linked employee", "account status"],
    sources: ["src/page/Admin/AdminDashboard.jsx", "src/page/Admin/CreateLinkedUserForm.jsx", "backend/api/user.php", "backend/api/force_change_password.php"],
    factSources: ["src/page/Admin/CreateLinkedUserForm.jsx", "backend/api/user.php", "backend/api/force_change_password.php"],
    answer: "Authorized administrators use User Management to create and maintain login accounts, assign roles and manage account status. Select the intended employee/account details and role, review the required fields, and save. Accounts can be linked to employee records; profile, PDS and personal records depend on that link. Newly issued temporary-password accounts must complete the forced password change before using ordinary modules. Inactive accounts cannot continue normal signed-in access. Account creation/activation messages use the configured mail service; a mail failure should be investigated separately from whether the account record was saved. Do not create a second account just to fix an incorrect employee link; ask an administrator to review the existing record."
  },
  {
    id: "account-login", category: "Account & access", title: "Sign-in, account activation, temporary passwords and recovery", keywords: ["login", "sign in", "google sign in", "forgot password", "reset password", "activation", "temporary password", "six digit code"],
    sources: ["src/components/UI_Login/", "backend/api/login.php", "backend/api/google_login.php", "backend/api/force_change_password.php", "backend/api/forgot_password.php", "backend/api/reset_password.php"],
    answer: "Sign in from the Login page using the configured account identifier/password or the available Google sign-in option. Complete any required CAPTCHA and emailed verification code. A new account issued a temporary password must replace it through the forced password-change form before entering ordinary modules. Use Forgot Password when you cannot authenticate; complete the recovery-code and new-password steps shown rather than asking another employee to share credentials. An inactive account, a temporary failed-attempt lock and an expired session are different states. Account creation/activation and recovery depend on the configured email service, approved email domains and current security settings. Creating an Admin account can additionally require a verification code in the Add User form."
  },
  {
    id: "divisions-positions", category: "Employees & organization", title: "Divisions, positions and organization structure", keywords: ["division", "position", "designation", "organization structure", "hierarchy", "salary grade", "work week"],
    sources: ["src/page/settings/division.jsx", "src/page/Admin/AdminDashboard.jsx"], extract: false,
    answer: "Use Divisions Management and Positions Management to maintain the organization catalog. A division groups employees and controls division-scoped reviews. A position is selected from the positions catalog and can have hierarchy/salary-grade information. The employee's optional designation is a separate assignment, such as an OIC title, and is not the same field as the position. Complete the applicable organization fields and save through the management screen. Unassigned employee division/position values can remain empty until an authorized user completes the record. Review dependencies before archiving catalog entries."
  },
  {
    id: "service-record", category: "Employees & organization", title: "Service records, imports and printable employment history", keywords: ["service record", "service history", "government service", "appointment", "import pdf", "salary history", "export service"],
    sources: ["src/module/serviceRecord/", "backend/api/service_record.php", "backend/api/service-record-import.php"],
    answer: "Open Service Record or My Service Record. Select the employee when your role manages other employees, then review dated appointment/history entries. Records include service dates, position/designation, employment status, station/branch, salary and grade/step fields where applicable. Authorized users can maintain and import service records using the available import dialog, review the extracted rows before saving, and print/download the service record. Employees use their own read-only history. Current appointment changes can append history; a service-history entry and today's employee master fields have different purposes. Do not assume an imported document has already been saved until its review/save action succeeds."
  },
  {
    id: "salary-notices", category: "Employees & organization", title: "Salary adjustments and salary/step increment notices", keywords: ["salary adjustment", "notice of salary adjustment", "notice of step increment", "nosa", "nosi", "step increment", "salary schedule"],
    sources: ["src/module/serviceRecord/ServiceRecordWorkspace.jsx", "src/module/serviceRecord/salarySchedule.js", "src/page/Admin/AdminDashboard.jsx"], extract: false,
    answer: "The admin workspace defines Salary Adjustment, Notice of Salary Adjustment and Notice of Step Increment views. Use the relevant salary/service-record view for the selected employee, review the grade, step, salary schedule and effective-date information supported by the form, and use its save/print/export controls. Grade and step describe the salary schedule placement; a designation title is a different field. Salary and appointment history should agree with the employee record and the effective notice. Only an authorized management role should correct salary master information."
  },
  {
    id: "profile-sections", category: "Profile & PDS", title: "All profile sections and saving changes", keywords: ["profile", "personal details", "family background", "educational background", "civil service eligibility", "learning development", "government ids", "address", "emergency contact"],
    sources: ["src/components/profile/ProfilePage.jsx", "src/components/profile/profileUtils.js", "src/components/profile/sections/", "backend/api/employee-pds-profile-utils.php"],
    answer: "My Profile has Personal Details, Family Background, Educational Background, Civil Service Eligibility, Learning & Development, Address, Government IDs, Employment Status, Emergency Contact, E-Signature and Security. Edit Profile enables the available editable sections and Save Changes saves changed sections. Cancel restores unsaved drafts; the photo/PDS photo preference and verified email are saved separately and retained. A protected Personal Details section requires an approved edit request from Admin or HR Head when the role cannot edit directly. The family section supports spouse, parents and children; education is grouped by level. Eligibility allows up to 31 entries and learning/development up to 61; dates must be valid, training end cannot precede its start, and training hours must be non-negative with up to two decimal places. A failed section load stays read-only to protect existing records."
  },
  {
    id: "signature-pds", category: "Profile & PDS", title: "E-signatures, PDS export and profile photo inclusion", keywords: ["e-signature", "signature", "pds", "passport photo", "photo inclusion", "excel", "pdf", "export"],
    sources: ["src/components/profile/sections/SignatureSection.jsx", "src/components/profile/ProfileImageModal.jsx", "src/services/personalDataSheetService.js", "backend/api/personal_data_sheet.php"],
    answer: "Save the employee's signature in the E-Signature profile section using its available drawing/upload controls. In Change Photo, upload and frame a portrait and set Include my profile picture in my PDS; Save Picture persists both the image and inclusion choice. The PDS photo uses the 3.5 cm wide by 4.5 cm high passport proportions. Export PDS Excel or Download PDS PDF builds the form from the signed-in employee's saved record and PDS sections, with the saved signature and optional photo. Save profile edits before exporting. An account without a linked employee record cannot export its own PDS."
  },
  {
    id: "leave-workflow", category: "Leave & requests", title: "Leave filing, review, approval and cancellation", keywords: ["leave workflow", "leave approval", "pending leave", "endorsed", "chief reviewed", "sick leave", "vacation leave", "cancel leave", "reject leave"],
    sources: ["src/module/leave/EmployeeLeaveWorkspace.jsx", "src/module/leave/LeaveDashboard.jsx", "src/components/leave/LeaveForm.jsx", "src/components/leave/LeaveReviewModal.jsx", "backend/api/leave_request.php"],
    answer: "File a leave request from the employee Leave Request page or the request workspace available to your role. Select type, dates and the required details; attach supporting material when required and submit. The standard approval chain is HR Staff credit verification (Pending to Endorsed), HR Head review (Reviewed), Division Chief review (Chief Reviewed), then Regional Director final approval (Approved). Planning Officers can perform configured division-desk actions when granted the corresponding leave approve/reject permission. The applicant's own role and division can cause documented stages to be skipped so an approver does not approve their own request. Review the current stage and available actions rather than applying the standard chain blindly. Rejections/cancellations and archiving have different effects. Personal-request roles are restricted to their own records."
  },
  {
    id: "leave-medical", category: "Leave & requests", title: "Sick-leave medical certificates and supporting attachments", keywords: ["medical certificate", "sick", "leave attachment", "supporting document", "certificate upload"],
    sources: ["src/components/leave/LeaveAttachmentUploadButton.jsx", "src/components/leave/LeaveAttachmentPreview.jsx", "src/components/leave/LeaveApplicationSheet.jsx", "backend/api/leave-medical-certificate-utils.php"],
    answer: "A leave form may require supporting attachments according to its type and duration. Sick-leave medical-certificate handling has its own upload and preview actions; use the available attachment control for the request and select an accepted file. The request list/details show the available upload action when the employee is allowed to provide the certificate. Review the displayed validation message for file size, type or missing-document requirements. Do not put medical details in the help chat; upload them through the protected request attachment form."
  },
  {
    id: "leave-credit-management", category: "Leave & requests", title: "Leave balances, COC credits, accrual and adjustments", keywords: ["leave balance management", "leave credits", "set leave balance", "coc", "compensatory credits", "opening balance", "accrual", "carry over"],
    sources: ["src/module/leave/LeaveBalanceManagementWorkspace.jsx", "src/components/leave/LeaveBalanceModal.jsx", "src/components/leave/LeaveCreditSnapshot.jsx", "backend/api/leave_credit.php", "backend/api/leave-credit-utils.php"],
    answer: "HR Staff and HR Head use Leave & COC Balances; Admin uses Leave Balance Management when permitted. Select the employee and the relevant year/credit type, review the existing balance and transactions, and use the displayed adjustment/save actions. The screen distinguishes leave credits from compensatory overtime credits. Pending requests can reserve available credits, and approval/cancellation workflows govern their consumption or release; do not manually double-deduct an approved request. The employee dashboard and filing forms expose the personal balance. Eligibility and available leave types depend on saved employee information and leave-type settings. Monetary values and current balances must be checked in the actual module."
  },
  {
    id: "leave-monetization", category: "Leave & requests", title: "Leave monetization filing and approval chain", keywords: ["monetization", "monetisation", "monetize leave", "cash conversion", "leave cash", "encash"],
    sources: ["src/components/leave/LeaveMonetizationFields.jsx", "src/module/leave/LeaveDashboard.jsx", "backend/api/leave_monetization.php", "backend/api/monetization-workflow.php"],
    answer: "Use the Leave Monetization option available in the leave workspace, select the employee and eligible credits, complete the monetization fields and submit. The implemented approval chain is HR Staff verification (Pending to Endorsed), HR Head (Reviewed), the Division Chief review (Chief Reviewed), then Regional Director (Approved); a Planning Officer may act as the configured division desk when permitted. Eligibility, credit availability and the form's validations still apply. A submitted application is not already converted to cash, and the assistant cannot calculate a binding entitlement or approve monetization."
  },
  {
    id: "travel-orders", category: "Leave & requests", title: "Travel-order filing, recommendation and approval", keywords: ["travel order", "travel approval", "planning officer", "recommended by", "destination", "official travel", "itinerary"],
    sources: ["src/module/travel/TravelOrderWorkspace.jsx", "backend/api/travel_order.php"],
    answer: "Open Travel Order/Travel Order Request under File Request, create an order and complete the traveller, dates, destination, purpose and other required fields. Submitted orders start Pending with the Planning Officer's recommendation. Recommendation moves the order to Reviewed and fills the Recommended by line; the traveller's Division Chief then signs it to Chief Reviewed, followed by the Regional Director's final approval. Request-only roles and division visibility have their own scoping rules. Review details/print the form using the available controls. Cancellation belongs to the traveller while an eligible order is still open; use the action shown rather than deleting the order."
  },
  {
    id: "compensatory-time-off", category: "Leave & requests", title: "CTO requests, COC consumption and division routing", keywords: ["cto", "compensatory time off", "coc", "half day", "unpaid hours", "expiry", "chief admin", "fad", "ord"],
    sources: ["src/module/compensatory/CompensatoryWorkspace.jsx", "backend/api/compensatory.php", "backend/api/compensatory-workflow-utils.php"],
    answer: "Open Compensatory Time Off and file the requested dates/half-days against the employee's available COC hours. A whole day consumes 8 hours and a half-day 4 hours; available paid hours are applied in half-day steps. Hours beyond covered credits are tracked as unpaid where the form permits them. The standard CTO route is Division Chief (Pending to Endorsed), Chief Admin (Reviewed), then Regional Director (Approved). FAD/FAM and ORD use the direct Chief Admin then Regional Director route. HR Head and HR Staff are not CTO approval desks. Check the credit year, expiry and reserved/pending hours displayed before filing."
  },
  {
    id: "pass-slips", category: "Leave & requests", title: "Pass slips, QR codes and departure/return scanning", keywords: ["pass slip", "pass slips", "qr", "scanner", "departure", "return time", "guard", "time out", "time returned"],
    sources: ["src/module/passslip/PassSlipWorkspace.jsx", "src/components/passslip/PassSlipQrPanel.jsx", "src/features/passSlipScanner/", "backend/api/pass_slip.php", "backend/api/pass-slip-utils.php", "backend/api/pass_slip_scan.php"],
    answer: "Open Pass Slips from File Request, complete the required purpose/date/time details, and submit for the review available to the request. The detail view exposes the pass-slip form and QR controls when applicable. The guard scanner is the dedicated /guard-scanner-qr page and supports the QR-token workflow for recording departure/return; it does not grant general account access. Scan the current request QR and review the scan result instead of manually inventing timestamps. The stored token, request status and recorded scan state determine whether the next action is allowed. Approved pass-slip hours can affect attendance/payroll calculations."
  },
  {
    id: "overtime", category: "Leave & requests", title: "Overtime requests, work dates and accomplishment reports", keywords: ["overtime", "ot", "accomplishment report", "memorandum", "overtime hours", "work dates", "overtime approval"],
    sources: ["src/module/overtime/", "backend/api/overtime.php", "backend/api/overtime-accomplishment-utils.php"],
    answer: "Use Overtime/Overtime Request in your portal, choose the employee and work dates, supply the required schedule and justification, and submit. The form provides work-date and time-selection controls and validates the requested period/hours. Follow the approval action appropriate to the current record and role. The overtime workspace includes an accomplishment-report memo workflow; complete the required accomplishment information and generate/print the supported report. Overtime approval, attendance logs, accomplishment documentation and credited compensatory hours are related records with separate validation; one saved request does not automatically establish all of them."
  },
  {
    id: "attendance-dtr", category: "Attendance & pay", title: "Attendance records, biometric imports and Daily Time Records", keywords: ["attendance", "dtr", "daily time record", "biometric", "dat", "excel attendance", "import attendance", "cutoff", "duplicate punches"],
    sources: ["src/module/attendance/", "backend/api/attendance.php"],
    answer: "Employees open My DTR to view their own records; management users use Attendance Records/Time & Attendance. HR Staff's Import Attendance workflow accepts the supported biometric .dat and Excel conversion modes, applies a selected cut-off and previews/processes the data. Review new punches, duplicates skipped, invalid rows, out-of-cut-off rows and daily/absent/leave counts in the import summary and import history. Set the period/employee filters to inspect records and use the DTR Excel/print actions where available. The saved employee signature can be included in DTR output. An empty current period can be a filter issue rather than missing historical imports. Only an authorized attendance role should correct/import records."
  },
  {
    id: "payroll-workflow", category: "Attendance & pay", title: "Payroll preparation, approval, returns and release", keywords: ["payroll", "payroll approval", "pending hr head", "pending chief", "pending director", "fad division chief", "returned for correction", "mark as paid", "registry"],
    sources: ["src/module/payroll/PayrollManagementWorkspace.jsx", "src/module/payroll/PayrollDetailDrawer.jsx", "src/module/payroll/PayrollRegistryDetailsView.jsx", "backend/api/payroll.php"],
    answer: "Open Payroll Management > Payroll. Authorized preparers select the payroll period and employee scope, review attendance, pay components, deductions and net pay, save a draft and submit. The approval chain is Pending HR Head (stored as Pending Approval), Pending FAD Division Chief (Pending Chief), then Pending Director (Pending Director), followed by Approved. The Cashier releases an approved batch using Mark as Paid, making it Paid. A rejection is displayed as Returned for Correction; correct and resubmit through the permitted action. Only the FAD/FAM Division Chief participates at the Chief payroll stage; Chief Admin and ordinary Division Chiefs do not inherit that desk. Register export is available after Approved or Paid. Review the record's current status and allowed actions; permission to view a register is not permission to prepare, approve or release it."
  },
  {
    id: "payroll-calculation", category: "Attendance & pay", title: "Payroll periods, attendance effects, deductions and payout halves", keywords: ["gross pay", "net pay", "pay period", "first half", "second half", "monthly", "deduction", "pera", "salary rate", "unpaid", "payout"],
    sources: ["src/module/payroll/payrollPayout.js", "src/module/payroll/PayslipWorkspace.jsx", "backend/api/payroll.php", "backend/api/payslip-deductions.php"],
    answer: "Payroll calculations use the saved salary/rate, selected period, attendance and approved request information, together with the configured earnings/deductions. Review the payroll detail instead of treating the basic salary as the net amount. Payout allocation follows the saved pay period: a 1st Half record allocates its net pay to the first half; a 2nd Half record to the second half; a Monthly record splits net pay between the halves with rounding reconciliation. No-days-worked payslips do not carry ordinary deductions or take-home pay. Use the payroll/payslip breakdown for current amounts; the assistant explains the workflow and does not read an employee's salary or calculate a binding payroll result."
  },
  {
    id: "payroll-verification", category: "Attendance & pay", title: "Payroll approval verification, CAPTCHA and email OTP", keywords: ["payroll otp", "payroll captcha", "workflow verification", "approval code", "step up", "verification code", "resend"],
    sources: ["src/module/payroll/payrollWorkflowCaptcha.js", "src/module/payroll/payrollWorkflowStepUp.js", "backend/api/workflow-otp-utils.php"],
    answer: "Sensitive payroll workflow actions can require the configured CAPTCHA and email-code verification. Start the action from the actual payroll record, complete the verification prompt, enter the code sent through the configured account mail flow and confirm within its validity period. Resending/retrying follows the displayed limits. A verified code applies to the intended action/record, not arbitrary later actions. Check the on-screen expiry, wrong-code or rate-limit message, and contact the system administrator if verification mail is unavailable. Never send an OTP to the help assistant."
  },
  {
    id: "loan-management", category: "Attendance & pay", title: "MGB Coop loan applications, approval, disbursement and payments", keywords: ["loan", "mgb coop", "cooperative", "loan application", "loan checklist", "disburse", "loan payment", "installment"],
    sources: ["src/module/Loan/", "src/components/payroll/LoanApplicationForm.jsx", "backend/api/loan_request.php"],
    answer: "Open Payroll Management > Loan. New applications use MGB Coop Loan; older government-product entries can still appear on existing loans but are not offered as new loan products. Select the employee, complete the application, review the employee checklist and calculated repayment information, and submit/save through the allowed action. The workspace supports loan status review, approval actions, disbursement and recording payments for the roles permitted by the backend. Repayment can be reflected through monthly payroll deductions. Review the saved loan's balance/payment history before recording another payment, and use archive/restore controls where available."
  },
  {
    id: "ipcr-performance", category: "Performance & development", title: "IPCR forms, KPI assignment, accomplishments and ratings", keywords: ["ipcr", "individual performance", "kpi", "success indicator", "target", "mov", "accomplishment", "individual rating"],
    sources: ["src/module/performance/EmployeeIpcrWorkspace.jsx", "src/module/performance/IpcrManagementWorkspace.jsx", "src/module/performance/KpiAssignmentTargetPicker.jsx", "src/module/performance/SuccessIndicatorsField.jsx", "backend/api/ipcr.php"],
    answer: "Employees use My IPCR; authorized management/review roles use Performance Management/Performance Reviews > IPCR. Choose the relevant form, period and employee scope. Management assigns KPIs/targets. The employee writes actual accomplishments, rates themselves on quantity, efficiency and timeliness, attaches MOVs, and submits. The Division Chief checks the MOVs and validates the rating, or returns the KPI with a correction note. Form group/category, success indicators, targets, accomplishments and the rating guide are separate parts of the same form. Use the actual exported/previewed form and saved ratings for official results."
  },
  {
    id: "opcr-performance", category: "Performance & development", title: "OPCR division commitments, MOV submission and Director validation", keywords: ["opcr", "office performance", "regional director validation", "mov", "division commitment", "quality", "efficiency", "timeliness"],
    sources: ["src/module/performance/OpcrManagementWorkspace.jsx", "src/module/performance/RatingGuide.jsx", "src/module/performance/RatingInput.jsx", "src/module/performance/successIndicators.js", "backend/api/opcr.php"],
    answer: "Use Performance Management/Performance Reviews > OPCR or the Regional Director's OPCR Validation page. Choose the form/period and division. The Division Chief writes KPI accomplishments, attaches the means of verification (MOVs), and submits the form. The Regional Director checks that evidence and validates/rates each KPI or returns it with a note. Quality, efficiency and timeliness inputs feed the average/final rating as implemented by the form; use N/A where the supported rating guide calls for it. A Chief's submission is evidence, not a Director's final rating. Review returned notes, update the required evidence and resubmit."
  },
  {
    id: "promotion-workflow", category: "Performance & development", title: "Promotion applications, stage results, attachments and final approval", keywords: ["promotion", "assessment", "examination", "interview", "submission for approval", "hr recommended", "not qualified", "promotion document", "promote"],
    sources: ["src/module/promotion/", "backend/api/promotion-workflow.php", "backend/api/promotion-documents.php", "backend/api/promotion.php"],
    answer: "Division Chiefs prepare eligible Regular employees' promotion applications within their division. The staged process is Assessment, Examination, Interview, Submission for Approval, HR Recommended, then Approved. At a stage, save its details without advancing, or move forward when the required result/fields are complete. Assessment records Qualified/Not Qualified; examination/interview record Passed/Failed. A Not Qualified outcome closes the application, while disapproval/cancellation are separate terminal results. HR Head recommends the completed submission and the Regional Director gives final approval. Supporting stage documents accept PDF, PNG/JPG/WebP, Word and Excel files up to 10 MB; the server checks document ownership and revisions. Employees' My Promotion view is read-only and scoped to their own approved promotions. Status/history and attachments are visible in the application details."
  },
  {
    id: "award-nominations", category: "Rewards & recognition", title: "Award cycles, Chief nominations, HR review and winners tally", keywords: ["award", "reward", "recognition", "nomination", "monthly cycle", "tally", "hr approved nominee", "employee of the month"],
    sources: ["src/module/rewards/AwardCyclesWorkspace.jsx", "src/module/rewards/NominationPortalUI.jsx", "src/module/rewards/awardCycleUtils.js", "backend/api/rewards.php"],
    answer: "The HR Head opens and manages award cycles and deadlines in the nominations workspace. Division Chiefs use Open Nominations to nominate an employee from their own division and supply the reason; My Nominations tracks their submissions. HR Head reviews pending nominations and approves/rejects each with the available note. Approved nominees enter the Winners Tally/employee voting pool. The Nominations, Pending, Recognized and Tally views serve different parts of the process. Cycle phase/deadline determines which actions are open. Closing a tied cycle requires resolving its tie through the supported process; it is not safe to assume the highest incomplete count is a final winner."
  },
  {
    id: "award-voting", category: "Rewards & recognition", title: "Employee award voting and My Rewards", keywords: ["award voting", "vote", "ballot", "nominee", "my rewards", "winner", "recognized", "voter"],
    sources: ["src/module/rewards/EmployeeVotingWorkspace.jsx", "src/module/rewards/MyRewardsWorkspace.jsx", "src/module/rewards/AwardVotersTable.jsx", "backend/api/rewards.php"],
    answer: "Employees use Award Voting to see approved nominees and cast one vote per award in an open cycle. They may change that vote until voting closes; voting again replaces the previous choice instead of adding a second vote. The server rejects voting for yourself, an unapproved nominee or a closed cycle. Employee ballots do not show vote counts until the cycle closes. The most-voted nominee wins and the certificate is issued when the cycle closes, subject to the supported tie-resolution process. My Rewards displays the signed-in employee's recorded recognition and available certificate information. A management account's ability to run nominations does not itself make it an Employee voter."
  },
  {
    id: "loyalty-awards", category: "Rewards & recognition", title: "Loyalty awards and service eligibility review", keywords: ["loyalty", "years of service", "service eligibility", "loyalty certificate", "award history"],
    sources: ["src/module/rewards/LoyaltyWorkspace.jsx", "src/module/rewards/loyaltyUtils.js", "backend/api/rewards.php"],
    answer: "Open R&R Management > Loyalty to review service-related award eligibility and recorded awards. Filter/select the applicable employee/year and review the saved service data and eligibility indicators before using the authorized recognition/certificate actions. Service dates and exclusions matter; a displayed year count alone is not an independent HR-policy determination. Keep recorded loyalty awards and certificate output consistent with the verified employee service record."
  },
  {
    id: "award-certificates", category: "Rewards & recognition", title: "Award certificate templates, preview and export", keywords: ["certificate template", "certificate editor", "award certificate", "background", "text placement", "certificate preview", "pdf certificate"],
    sources: ["src/module/rewards/CertificateTemplateEditor.jsx", "src/module/rewards/AwardCertificate.jsx", "src/module/rewards/editableCertificateTemplate.js", "src/module/rewards/certificateTemplate.js"],
    answer: "Authorized users open R&R Management > Certificate Template to edit the supported certificate layout and preview its appearance. Configure the available text, artwork/layout and signatory elements, save the template, then generate/preview the certificate for the appropriate recognized employee/award. Template editing changes presentation; it does not create an approved award record by itself. Review the employee name, award, dates and signatories in the final preview before printing or exporting."
  },
  {
    id: "reports-analytics", category: "Reports & calendar", title: "Report catalog, categories, filters, preview and exports", keywords: ["report", "reports", "analytics", "export report", "employee report", "payroll report", "leave report", "travel report", "cto report", "attendance report", "performance report", "audit report"],
    sources: ["src/module/reports/", "backend/api/reports.php"],
    answer: "Open Reports & Analytics and choose an available category: Employee, Payroll, Leave, Travel Order, CTO, Attendance, Performance or Audit. Choose the report in the catalog, set its employee/division/date/status filters, review the table/charts or report preview, and use the displayed print/Excel/PDF export options. Report categories and record scope depend on the role and permissions; Audit is intentionally hidden from several portals, and division users do not automatically see organization-wide records. Counts reflect the selected filters and report definitions. Archived, pending, paid and approved records may be handled differently by different reports, so check the report's label and preview."
  },
  {
    id: "calendar-announcements", category: "Reports & calendar", title: "Calendars, leave/travel schedules, holidays and announcements", keywords: ["calendar", "schedule", "holiday", "announcement", "event", "upcoming", "office activity"],
    sources: ["src/module/calendar/", "src/components/calendar/calendar.jsx", "src/components/dashboard/DashboardLeaveTravelCalendar.jsx", "src/components/dashboard/DashboardMonthlyCalendar.jsx", "backend/api/holiday.php", "backend/api/announcement.php"],
    answer: "Use the calendar or dashboard schedule to review office dates, holidays, announcements and visible leave/travel activities. Navigate the month, select an activity and open its details; employee activities and office-wide events are distinct. Authorized users maintain holiday/announcement records with the available create/edit/archive controls. Calendar visibility does not itself approve a leave/travel request. Request approval and record access remain enforced in their original modules."
  },
  {
    id: "messages-notifications", category: "Communication", title: "Messages, header chat and notification updates", keywords: ["message", "messenger", "chat", "conversation", "unread", "notification", "bell", "attachment", "group"],
    sources: ["src/components/bubble_chat/", "src/components/notification/", "backend/api/messages.php", "backend/api/notifications.php"],
    answer: "Use Messages or the header chat control to select a conversation and send a message through the available composer/attachment actions. The header messenger and full Messages page are two views of the communication feature. Use the notification bell/Notifications page for system events and approval updates; opening a notification can lead to its module. Unread indicators describe message/notification state, not the number of requests pending at your approval desk. Messages and notifications are shared signed-in utilities, while the linked record still requires its own access permission. Help & FAQ is a separate AI/system guide conversation and does not send a message to HR staff."
  },
  {
    id: "settings-overview", category: "Settings & administration", title: "Settings navigation and configuration sections", keywords: ["settings", "configuration", "preferences", "filter settings", "system configuration"],
    sources: ["src/page/settings/division.jsx", "src/components/settings/SettingsNav.jsx"],
    answer: "Open Settings from an authorized account and use Filter settings to find a section. Configuration areas include preferences, organization/positions, leave types, addresses, deductions, signatories/payroll signatories, roles and permissions, two-factor authentication, email-domain policy, password/login lock settings, math CAPTCHA, request rate limiting, audit logs and backup/restore. Each section has its own fields and save action. Do not assume changing one panel automatically saves every other panel. The actual available settings are controlled by the account's permissions."
  },
  {
    id: "settings-leave-types", category: "Settings & administration", title: "Leave types, eligibility, requirements and active status", keywords: ["leave types", "leave type settings", "add leave type", "leave type inactive", "gender eligibility", "leave requirements"],
    sources: ["src/page/settings/leavetypes.jsx", "backend/api/settings.php"],
    answer: "Open Settings > Leave Types. Add or edit a type using the available name, eligibility, credit/limit and requirement fields, review its active status, and save. Active/inactive status controls whether a type is offered for new filing; existing requests retain their recorded type/history. Eligibility can depend on employee information such as gender and the type's configured rules. If a type is missing from a leave form, check both its active setting and the employee's eligibility rather than creating a duplicate type."
  },
  {
    id: "settings-addresses", category: "Settings & administration", title: "Address settings and dependent address selectors", keywords: ["address settings", "add address", "region", "province", "city", "municipality", "barangay", "zip code", "psgc"],
    sources: ["src/page/settings/addresses.jsx", "src/utils/addressDirectory.js", "src/hooks/useAddressDirectory.js"],
    answer: "Settings > Add Address/Addresses supplements the compiled Philippine address directory. Maintain the supported region/province/city/barangay entries and save the change. Address forms use dependent selectors, so select the parent location before a child location. An address added in settings appears through the shared address directory; it is different from changing one employee's street/address fields in My Profile. Review the hierarchy and duplicates when a desired barangay/city is not listed."
  },
  {
    id: "settings-deductions", category: "Settings & administration", title: "Deduction catalog, amounts and payroll deductions", keywords: ["deduction settings", "deduction catalog", "other deductions", "add deduction", "statutory", "monthly deduction"],
    sources: ["src/page/settings/deductions.jsx", "backend/api/deduction-catalog.php", "backend/api/deduction.php"],
    answer: "Open Settings > Deductions to maintain the available deduction catalog and supported configuration. Complete the name/type and amount/rule fields shown, then save. Catalog entries define deductions offered to payroll workflows; an employee's recorded loan repayment or a specific payroll deduction is a separate record. Review active/status and dependency information before archiving a catalog item. The payroll/payslip details show the deductions actually applied to a saved period."
  },
  {
    id: "settings-signatories", category: "Settings & administration", title: "Filing signatories and payroll signatory configuration", keywords: ["signatory", "signatories", "recommended by", "approved by", "prepared by", "certified", "payroll signatories", "signature missing"],
    sources: ["src/page/settings/signatories_management.jsx", "src/page/settings/payroll_signatories.jsx", "src/hooks/useFilingSignatories.js", "backend/api/payroll-signatories.php"],
    answer: "Use Signatories Management for the relevant filing forms and Payroll Signatories for payroll-specific signatory settings. Select the supported person/role/line and save. Form signatory labels and actual recorded workflow signatures have different purposes: changing a default signatory does not retrospectively approve a request. A missing signature can come from an unset signatory, missing saved employee e-signature, or a stage that has not been signed. Review the form and the employee's E-Signature settings before regenerating an output."
  },
  {
    id: "settings-roles-permissions", category: "Settings & administration", title: "Custom roles, RBAC and permission overrides", keywords: ["rbac", "roles", "permissions", "role based access control", "custom role", "base role", "grant", "access request"],
    sources: ["src/page/settings/roles.jsx", "src/page/settings/permission.jsx", "src/components/layout/RoleWorkspacePage.jsx", "backend/api/roles.php", "backend/api/permissions.php", "backend/api/access_request.php"],
    answer: "Use Roles to maintain supported role definitions and base roles, and Role Based Access Control/Permissions to manage module/action access. Select the role/user, review enabled modules and their actions, then save the intended template or user override. Custom roles route through a configured base role; module permissions are still checked separately. View, create, update, approve/reject and other actions can have different grants, and workflow stage/record scope can further restrict them. The access-denied screen can provide an access-request action. Submitting that request asks an authorized administrator to review access; it does not grant it immediately."
  },
  {
    id: "settings-preferences", category: "Settings & administration", title: "System preferences, theme and session configuration", keywords: ["preferences", "dark mode", "light mode", "theme", "accent", "color", "session timeout", "inactivity"],
    sources: ["src/page/settings/preferences.jsx", "src/components/darkmode/darkmodetoggle.jsx", "src/components/theme/systemTheme.js", "src/App.jsx"],
    answer: "Use the header theme toggle for light/dark appearance and the available preference controls for supported system/theme options. Authorized system preferences can govern session inactivity and other global choices shown by the panel. Save global configuration through its own save action. The app warns near session expiry and can sign out an inactive account; background dashboard refreshes do not substitute for user activity. Unsaved form navigation may trigger a save/discard guard before changing pages."
  },
  {
    id: "settings-two-factor", category: "Settings & administration", title: "System two-factor authentication and personal 2FA", keywords: ["two factor", "two-factor", "2fa", "otp", "email verification", "login code", "personal 2fa"],
    sources: ["src/page/settings/twofactorauthentication.jsx", "src/components/profile/sections/SecuritySection.jsx", "backend/api/two_factor.php"],
    answer: "Administrators configure system two-factor authentication in Settings. A user manages Personal 2FA from My Profile > Security. Personal verification is applied according to the system's enabled/required rules; the Security page shows whether verification is available or required and offers relevant history. During login, use the emailed code and the displayed resend/expiry behavior. A required system rule cannot be bypassed by toggling an unrelated profile field. If verification mail does not arrive, use the supported resend option within its limits and contact the administrator."
  },
  {
    id: "settings-email-domains", category: "Settings & administration", title: "Email-domain policy and email change verification", keywords: ["email domain", "domain policy", "allowed domains", "email address", "change email", "gmail", "domain rejected"],
    sources: ["src/page/settings/email_domain_policy.jsx", "src/components/profile/sections/ChangeEmailSection.jsx", "src/components/profile/sections/ProfileEmailChangeSection.jsx", "backend/api/email-domain-policy.php", "backend/api/email_verification.php"],
    answer: "Use Settings > Email Domain Policy to configure the permitted account email domains. A domain rule concerns the part after @; an address accepted elsewhere is not necessarily permitted by the account policy. Users change their email through the profile's verified email-change flow, which requests a code for the currently registered address before the change is applied. Follow the on-screen verification steps and save/confirm the intended new address. Updating a plain text field outside that verified flow is not equivalent to changing the account login email."
  },
  {
    id: "settings-lockout", category: "Settings & administration", title: "Failed login attempts, lockout and password expiry", keywords: ["lock attempts", "account locked", "failed login", "lockout", "password expiry", "expired password", "forgot password", "temporary password"],
    sources: ["src/page/settings/lockattempt.jsx", "src/components/auth/PasswordExpiryModal.jsx", "src/components/profile/sections/PasswordChangeSection.jsx", "backend/api/password_expiry_check.php", "backend/api/password-reset-utils.php"],
    answer: "Settings > Lock Attempts governs the supported failed-login/lock behavior. Users see password-expiry warnings in their profile/account UI and may be required to change an issued temporary password before using the app. Use the profile Change Password action with the required current/new confirmation fields; when unable to sign in, use Forgot Password and complete the configured recovery flow. Lockout and rate limiting are separate controls, so review the actual displayed message and wait period rather than repeatedly submitting guesses."
  },
  {
    id: "settings-captcha", category: "Settings & administration", title: "Math CAPTCHA and verification prompts", keywords: ["math captcha", "captcha", "challenge", "math verification", "wrong answer", "captcha settings"],
    sources: ["src/page/settings/math_captcha.jsx", "backend/api/captcha-utils.php", "backend/api/captcha.php"],
    answer: "Authorized users configure the supported Math CAPTCHA settings in Settings. CAPTCHA challenges can be used for login or protected workflow actions according to their purpose. Complete the current challenge in the actual dialog and submit before its validity expires; a challenge for one purpose does not automatically authorize another. Refresh/request a challenge using the provided control if it is expired or unreadable, and follow the retry limit shown."
  },
  {
    id: "settings-rate-limits", category: "Settings & administration", title: "Rate limiting, request filing limits and retry periods", keywords: ["rate limit", "too many requests", "429", "filing limit", "request limit", "blocked", "retry after"],
    sources: ["src/page/settings/rate_limiting.jsx", "backend/api/rate-limit.php", "backend/api/throttle.php"],
    answer: "Settings > Rate Limiting lets authorized administrators configure enabled limits, request counts, time windows and blocking periods for the supported groups. Groups include sign-in attempts, password-reset requests/codes, two-factor verification, shared request filing and general API traffic. The filing allowance is shared across request modules for the filing account, rather than resetting when switching from leave to travel or CTO. A rate-limited response provides a retry period; wait for it instead of repeatedly resubmitting. Changing global limits affects other users and should be done deliberately by an authorized administrator."
  },
  {
    id: "settings-audit", category: "Settings & administration", title: "Audit logs, action history and login activity", keywords: ["audit", "audit logs", "activity logs", "login history", "who changed", "history", "action trail"],
    sources: ["src/page/settings/auditlogs.jsx", "backend/api/audit_logs.php"],
    answer: "Open Audit Logs with a role permitted to view them. Use the available search, actor/module/action/date filters to investigate recorded activity and open the supported details or exports. Audit data describes recorded events; it is different from the current live record and from a request's stage-history panel. Profile Security can separately show the current user's verification/login history. Report-category visibility may hide Audit from some report sidebars even when a separate audit permission exists."
  },
  {
    id: "settings-backup", category: "Settings & administration", title: "Database backup, scheduled backup and restore", keywords: ["backup", "restore", "database", "download backup", "schedule backup", "restore sql"],
    sources: ["src/page/settings/backup_data.jsx", "backend/api/backup.php"],
    answer: "Authorized administrators use Backup Data to inspect the supported backup list/settings, generate/download a backup, and use the restore workflow when necessary. Review the backup source, date and target before restoring: restoring database content can replace the current records and is not an ordinary undo button. Follow the interface's confirmations and use a known backup appropriate to the intended recovery. A downloadable backup and uploaded employee documents have separate storage/lifecycle concerns. The help assistant can explain the interface but cannot execute a restore."
  },
  {
    id: "archive-and-errors", category: "System & roles", title: "Archives, missing records, validation and troubleshooting", keywords: ["archive", "restore", "deleted", "missing records", "validation", "error", "network", "loading", "session expired", "not found", "save failed"],
    sources: ["src/components/UI/ArchiveViewToggle.jsx", "src/page/NotFoundPage.jsx", "src/utils/navigationGuard.js", "src/services/api.js"], extract: false,
    answer: "If a record is missing, check employee/division/date/status filters and the archive toggle before assuming deletion. Archive/restore hides or returns records according to the module; it does not approve a request or reverse a financial workflow. A validation message means the relevant field/file/period needs correction before saving. A session-expired or inactive-account message requires the appropriate sign-in/account recovery, while Access Denied requires permission review. A page not found can be a wrong route or role portal. Preserve unsaved information when a save fails and retry the failed operation after its cause is resolved rather than duplicating the entire record."
  },
  {
    id: "assistant-connection", category: "System & roles", title: "Help assistant, chat history, system guides and AI connection", keywords: ["ai", "assistant", "faq", "help", "nvidia", "api key", "not responding", "system guide", "all functions", "chat history", "recent chats", "new chat", "delete chat"],
    sources: ["src/components/help/FaqAssistant.jsx", "src/components/help/FaqChatHistory.jsx", "src/components/help/faqHistory.js", "src/services/faqService.js"], extract: false,
    answer: "The question-mark icon beside the header theme control opens Help & FAQ; on mobile it floats above the messages button. Ask a natural-language question about any documented system module or browse/search the system guides. The plus button starts a new chat. History lists your ten most recent completed conversations with titles and dates; reopen a chat to continue it or use its delete button to remove it. Chats are saved separately for each signed-in account in this browser, survive a reload, and do not sync to other browsers or devices. Clearing site storage removes local history. The assistant selects relevant module documentation and uses signed-in role/permission context for its guidance. It explains workflows and errors; it does not execute actions or access employee/payroll records. If NVIDIA is unavailable, it labels the matching built-in answer as System FAQ. The administrator configures the NVIDIA connection privately on the backend using NVIDIA_API_KEY and the model setting; never paste credentials into the help chat."
  }
];
